import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";

const App = () => {
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const move = (e) => setMousePos({ x: e.clientX, y: e.clientY });
    window.addEventListener("mousemove", move);
    return () => window.removeEventListener("mousemove", move);
  }, []);

  // --- STYLES ---
  const container = {
    background: "#050505",
    minHeight: "100vh",
    color: "#f5f5f5",
    fontFamily: "'Inter', sans-serif",
    position: "relative",
    overflow: "hidden",
    padding: "40px"
  };

  // 🎯 RGBRO Cursor Glow
  const cursorGlow = {
    position: "fixed",
    width: "100%",
    height: "100%",
    pointerEvents: "none",
    zIndex: 1,
    background: `
      radial-gradient(500px at ${mousePos.x}px ${mousePos.y}px, rgba(255, 59, 59, 0.15), transparent 70%),
      radial-gradient(400px at ${mousePos.x - 100}px ${mousePos.y - 100}px, rgba(41, 121, 255, 0.12), transparent 70%),
      radial-gradient(300px at ${mousePos.x + 120}px ${mousePos.y + 80}px, rgba(255, 214, 0, 0.10), transparent 70%)
    `
  };

  // 🎯 HERO TITLE
  const title = {
    fontSize: "5rem",
    fontWeight: "900",
    textAlign: "center",
    marginTop: "100px",
    fontFamily: "'Playfair Display', serif",
    background:
      "linear-gradient(90deg, #FF3B3B, #FF8C00, #FFD600, #2979FF)",
    WebkitBackgroundClip: "text",
    WebkitTextFillColor: "transparent",
    textShadow: "0 0 40px rgba(255,140,0,0.3)"
  };

  const subtitle = {
    textAlign: "center",
    color: "#a0a0a0",
    marginTop: "10px",
    letterSpacing: "2px"
  };

  // 🎯 CARDS
  const cardContainer = {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
    gap: "30px",
    maxWidth: "1100px",
    margin: "80px auto",
    zIndex: 10,
    position: "relative"
  };

  const card = {
    background: "rgba(20,20,20,0.6)",
    backdropFilter: "blur(20px)",
    borderRadius: "20px",
    padding: "30px",
    border: "1px solid rgba(255,255,255,0.08)",
    transition: "all 0.4s ease"
  };

  const sections = [
    { name: "Achievements", color: "#FF3B3B" },
    { name: "Memories", color: "#2979FF" },
    { name: "Events", color: "#FF8C00" }
  ];

  return (
    <div style={container}>
      {/* Cursor Glow */}
      <div style={cursorGlow}></div>

      {/* HERO */}
      <motion.div
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 1 }}
        style={{ zIndex: 10, position: "relative" }}
      >
        <h1 style={title}>Hamdard Alumni</h1>
        <p style={subtitle}>
          Excellence • Legacy • Community
        </p>
      </motion.div>

      {/* CARDS */}
      <div style={cardContainer}>
        {sections.map((item, i) => (
          <motion.div
            key={i}
            style={card}
            whileHover={{
              scale: 1.05,
              y: -10,
              boxShadow: `0 20px 50px ${item.color}40`
            }}
          >
            {/* Glow Dot */}
            <div
              style={{
                width: "45px",
                height: "45px",
                borderRadius: "50%",
                background: item.color,
                marginBottom: "20px",
                boxShadow: `0 0 25px ${item.color}`
              }}
            />

            <h2 style={{ fontSize: "1.6rem", marginBottom: "10px" }}>
              {item.name}
            </h2>

            <p style={{ color: "#aaa", lineHeight: "1.6" }}>
              Explore our alumni journey, achievements, and memorable moments
              that define our legacy.
            </p>
          </motion.div>
        ))}
      </div>

      {/* BACKGROUND ORBS */}
      <div
        style={{
          position: "absolute",
          top: "-150px",
          right: "-150px",
          width: "400px",
          height: "400px",
          background: "rgba(255, 59, 59, 0.15)",
          filter: "blur(120px)",
          borderRadius: "50%"
        }}
      />
      <div
        style={{
          position: "absolute",
          bottom: "-150px",
          left: "-150px",
          width: "400px",
          height: "400px",
          background: "rgba(41, 121, 255, 0.15)",
          filter: "blur(120px)",
          borderRadius: "50%"
        }}
      />
    </div>
  );
};

export default App;
